/* 开机时打印芯片信息，便于定位批次差异 */
printf("REVID = 0x%04X\r\n", (unsigned)DBGMCU_GetREVID());
printf("DEVID = 0x%04X\r\n", (unsigned)DBGMCU_GetDEVID());

/* 注意返回值的高 16 位才是修订号，低 16 位是 0 */
if (DBGMCU_GetREVID() == 0x1000)
{
  /* Rev A 硅片，部分外设有已知勘误，必要时做规避 */
}

/* 运行时识别芯片容量，决定可用外设 */
switch (DBGMCU_GetDEVID())
{
  case 0x410:  /* 中容量：C8T6 属于这一类，无 DAC/FSMC/SDIO */
    break;
  case 0x414:  /* 大容量：有 DAC、FSMC */
    break;
  default:
    break;
}

/* 在 main 开头、初始化外设之前调用最稳妥 */
int main(void)
{
  /* 1. 冻结看门狗：断点期间不被复位，否则单步调试根本进行不下去 */
  DBGMCU_Config(DBGMCU_IWDG_STOP, ENABLE);
  DBGMCU_Config(DBGMCU_WWDG_STOP, ENABLE);

  /* 2. 冻结定时器：断点期间停止计数，避免恢复后中断集中爆发 */
  DBGMCU_Config(DBGMCU_TIM1_STOP | DBGMCU_TIM2_STOP
              | DBGMCU_TIM3_STOP | DBGMCU_TIM4_STOP, ENABLE);

  /* 3. 冻结 CAN：避免断点期间 FIFO 被总线上其它节点塞满 */
  DBGMCU_Config(DBGMCU_CAN1_STOP, ENABLE);

  /* 4. 之后才是常规外设初始化 */
  IWDG_Enable();
  /* ... */
}
